<?php
/** Proof — triggers (spec "Proof", 5): on create of an urgent ticket from a Gold organization the trigger sets the queue and priority after the create committed; a trigger that throws leaves the ticket; a trigger never fires itself (depth 1); a trigger on reply and on note. */
require __DIR__ . '/lib.php';
$W = world();
$marco = as_member(27); $owner = as_member(1);
act($owner, '/settings/queues/member.php', ['queue' => general_queue(), 'member' => 27]);
echo "1. On create\n";
[$c, $b] = act($owner, '/settings/automation/save.php', ['name' => 'SMOKE Gold urgent to IT', 'kind' => 'trigger', 'event' => 'ticket.create', 'conditions' => json_encode(['all' => [['field' => 'organization_id', 'op' => 'eq', 'value' => $W['org']], ['field' => 'priority', 'op' => 'in', 'value' => ['high', 'urgent']]]]), 'actions' => json_encode([['assign' => ['queue_id' => $W['it']]], ['set' => ['priority' => 'urgent']], ['add_tags' => ['gold']]])]);
$rule = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $rule > 0, 'the trigger saved');
$since = last_activity_id();
$t = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE gold and high', 'body' => 'x', 'queue' => general_queue(), 'requester' => $W['jo'], 'priority' => 'high'])[1]['record_id'];
$row = ticket_row($t);
ok((int) $row['queue_id'] === $W['it'] && $row['priority'] === 'urgent' && in_array('gold', pg_text_array((string) one('SELECT tags FROM mcp_tickets WHERE ticket_id = :t', ['t' => $t])), true), 'after the create: in IT, urgent, tagged gold');
$log = q("SELECT action, after FROM activity_log WHERE ticket_id = :t AND id > :s ORDER BY id", ['t' => $t, 's' => $since]);
$acts = array_map(fn ($x) => $x['action'], $log);
ok($acts[0] === 'ticket.create' && in_array('rule.fire', $acts, true) && array_search('rule.fire', $acts, true) > 0, 'ticket.create was committed before the rule fired (' . implode(' → ', $acts) . ')');
$fire = array_values(array_filter($log, fn ($x) => $x['action'] === 'rule.fire'))[0];
ok(json_decode($fire['after'], true)['outcome'] === 'applied' && count(rule_runs_of($rule)) === 1, 'rule.fire applied; one rule_runs row');
$assign = array_values(array_filter($log, fn ($x) => $x['action'] === 'ticket.assign'))[0] ?? null;
ok($assign !== null && json_decode($assign['after'], true)['via'] === 'trigger' && json_decode($assign['after'], true)['rule_id'] === $rule, 'the queue move logged via trigger with the rule id');
$t2 = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE gold but low', 'body' => 'x', 'queue' => general_queue(), 'requester' => $W['jo'], 'priority' => 'low'])[1]['record_id'];
ok((int) ticket_row($t2)['queue_id'] === general_queue() && count(rule_runs_of($rule)) === 1, 'a low one does not match: untouched, no run');
echo "2. A trigger that throws\n";
$boom = plant_rule('SMOKE trigger boom', 'trigger', [], [['set' => ['due_at' => 'not-a-date']]], 'ticket.create', 1);
$t3 = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE survives the boom', 'body' => 'x', 'queue' => $W['it']])[1]['record_id'];
ok($t3 > 0 && ticket_row($t3)['subject'] === 'SMOKE survives the boom' && rule_runs_of($boom)[0]['outcome'] === 'error', 'the ticket exists; the trigger\'s run is an error');
q('UPDATE automation_rules SET active = false WHERE id = :r', ['r' => $boom]);
echo "3. Depth 1\n";
$up = plant_rule('SMOKE update loops', 'trigger', ['all' => [['field' => 'priority', 'op' => 'neq', 'value' => 'low']]], [['set' => ['priority' => 'low']], ['note' => 'lowered by the rule']], 'ticket.update', 2);
$n = count(rule_runs_of($up));
[$c, $b] = act($marco, '/tickets/fields.php', ['ticket' => $t3, 'priority' => 'high']);
ok($c === 200 && ticket_row($t3)['priority'] === 'low' && count(rule_runs_of($up)) === $n + 1, 'a ticket.update trigger fired once on the change and set the priority low');
ok((int) one("SELECT count(*) FROM messages WHERE ticket_id = :t AND body_text = 'lowered by the rule'", ['t' => $t3]) === 1, 'its own set_fields fired no second round (one note)');
q('UPDATE automation_rules SET active = false WHERE id = :r', ['r' => $up]);
echo "4. On reply and on note\n";
$rr = plant_rule('SMOKE tag on reply', 'trigger', [], [['add_tags' => ['replied']]], 'ticket.reply', 3);
$nr = plant_rule('SMOKE tag on note', 'trigger', [], [['add_tags' => ['noted']]], 'ticket.note', 4);
act($marco, '/tickets/reply.php', ['ticket' => $t3, 'body' => 'hello']);
act($marco, '/tickets/note.php', ['ticket' => $t3, 'body' => 'a note']);
$tags = pg_text_array((string) one('SELECT tags FROM mcp_tickets WHERE ticket_id = :t', ['t' => $t3]));
ok(in_array('replied', $tags, true) && in_array('noted', $tags, true), 'ticket.reply and ticket.note triggers fired');
q('UPDATE automation_rules SET active = false WHERE id IN (:a, :b)', ['a' => $rr, 'b' => $nr]);
echo "5. The public form and the mail fire ticket.create too\n";
$fr = plant_rule('SMOKE tag from the form', 'trigger', [['field' => 'channel', 'op' => 'eq', 'value' => 'form']] ? ['all' => [['field' => 'channel', 'op' => 'eq', 'value' => 'form']]] : [], [['add_tags' => ['from-form']]], 'ticket.create', 9);
$v = jar(); req('GET', '/request', ['jar' => $v]);
$tok = csrf_of(req('GET', '/request', ['jar' => $v])['body']);
req('POST', '/request', ['jar' => $v, 'form' => ['csrf_token' => $tok, 'name' => 'Gold', 'email' => 'gold@customer.invalid', 'subject' => 'SMOKE from the form', 'body' => 'x']]);
$tf = (int) one("SELECT id FROM tickets WHERE subject = 'SMOKE from the form'");
ok($tf > 0 && in_array('from-form', pg_text_array((string) one('SELECT tags FROM mcp_tickets WHERE ticket_id = :t', ['t' => $tf])), true) && count(rule_runs_of($fr)) === 1, 'a request from the form fires ticket.create triggers too (tagged from-form)');
q('UPDATE automation_rules SET active = false WHERE id = :r', ['r' => $fr]);
finish();
